export type VisualizerMode = "bars" | "wave" | "circular";

export type VisualizerSource = HTMLMediaElement | MediaStream | AudioBuffer;

export interface VisualizerConfig {
  mode?: VisualizerMode; // default "bars"
  /** Power-of-two, 32–32768. Higher = more frequency resolution, more CPU. Default 256. */
  fftSize?: number;
  /** 0–1, higher = smoother/slower-responding data. Default 0.8. */
  smoothingTimeConstant?: number;
  /** Number of bars to render in "bars" mode. Derived from fftSize if omitted. */
  barCount?: number;
  gapRatio?: number; // gap between bars as a fraction of bar width, "bars" mode. Default 0.3.
  color?: string; // solid color, or omit and use colorStops for a gradient
  colorStops?: { offset: number; color: string }[];
  backgroundColor?: string; // default "transparent"
  lineWidth?: number; // "wave"/"circular" stroke width. Default 2.
  /** Radius as a fraction of the canvas's shorter dimension, "circular" mode. Default 0.35. */
  circularRadiusRatio?: number;
}

export interface VisualizerEngine {
  connect: (source: VisualizerSource) => void;
  disconnect: () => void;
  start: () => void;
  stop: () => void;
  setMode: (mode: VisualizerMode) => void;
  setConfig: (patch: Partial<VisualizerConfig>) => void;
  isRunning: () => boolean;
  getMode: () => VisualizerMode;

  /** Attach the canvas element the engine renders into. */
  attachCanvas: (el: HTMLCanvasElement | null) => void;

  /** Resumes a suspended AudioContext — call from a user-gesture handler (autoplay policy). */
  resume: () => Promise<void>;

  subscribe: (listener: () => void) => () => void; // fires on isRunning/mode changes only, NOT per-frame
  destroy: () => void;
}

export interface VisualizerContextValue {
  engine: VisualizerEngine;
  config: Required<VisualizerConfig>;
  isRunning: boolean;
  mode: VisualizerMode;
}

import type {
  VisualizerConfig,
  VisualizerEngine,
  VisualizerMode,
  VisualizerSource,
} from "./types";

const DEFAULT_CONFIG: Required<VisualizerConfig> = {
  mode: "bars",
  fftSize: 256,
  smoothingTimeConstant: 0.8,
  barCount: 48,
  gapRatio: 0.3,
  color: "#c2f13c",
  colorStops: [],
  backgroundColor: "transparent",
  lineWidth: 2,
  circularRadiusRatio: 0.35,
};

// createMediaElementSource() throws if called twice on the same element, so we
// cache the source node per element rather than trying to recreate it on reconnect.
const mediaElementSourceCache = new WeakMap<HTMLMediaElement, MediaElementAudioSourceNode>();

export function createVisualizerEngine(configInput: VisualizerConfig = {}): VisualizerEngine {
  let config: Required<VisualizerConfig> = { ...DEFAULT_CONFIG, ...configInput };

  let audioContext: AudioContext | null = null;
  let analyser: AnalyserNode | null = null;
  let sourceNode: AudioNode | null = null;
  let canvasEl: HTMLCanvasElement | null = null;

  let running = false;
  let rafId: number | null = null;
  let freqData: Uint8Array<ArrayBuffer> | null = null;
  let timeData: Uint8Array<ArrayBuffer> | null = null;

  const listeners = new Set<() => void>();
  function notify() {
    listeners.forEach((l) => l());
  }

  function ensureContext() {
    if (audioContext) return;
    audioContext = new AudioContext();
    analyser = audioContext.createAnalyser();
    analyser.fftSize = config.fftSize;
    analyser.smoothingTimeConstant = config.smoothingTimeConstant;
    freqData = new Uint8Array(new ArrayBuffer(analyser.frequencyBinCount));
    timeData = new Uint8Array(new ArrayBuffer(analyser.frequencyBinCount));
  }

  function resolveColorStyle(ctx: CanvasRenderingContext2D, height: number): string | CanvasGradient {
    if (config.colorStops.length > 0) {
      const gradient = ctx.createLinearGradient(0, height, 0, 0);
      config.colorStops.forEach((s) => gradient.addColorStop(s.offset, s.color));
      return gradient;
    }
    return config.color;
  }

  function drawBars(ctx: CanvasRenderingContext2D, w: number, h: number) {
    if (!analyser || !freqData) return;
    analyser.getByteFrequencyData(freqData);

    const barCount = Math.min(config.barCount, freqData.length);
    const binsPerBar = Math.floor(freqData.length / barCount) || 1;
    const barWidth = w / barCount;
    const gap = barWidth * config.gapRatio;

    ctx.fillStyle = resolveColorStyle(ctx, h);
    for (let i = 0; i < barCount; i++) {
      let sum = 0;
      for (let j = 0; j < binsPerBar; j++) sum += freqData[i * binsPerBar + j] ?? 0;
      const avg = sum / binsPerBar / 255;
      const barHeight = avg * h;
      const x = i * barWidth + gap / 2;
      ctx.fillRect(x, h - barHeight, barWidth - gap, barHeight);
    }
  }

  function drawWave(ctx: CanvasRenderingContext2D, w: number, h: number) {
    if (!analyser || !timeData) return;
    analyser.getByteTimeDomainData(timeData);

    ctx.strokeStyle = resolveColorStyle(ctx, h);
    ctx.lineWidth = config.lineWidth;
    ctx.beginPath();

    const step = w / timeData.length;
    for (let i = 0; i < timeData.length; i++) {
      const v = timeData[i] / 128 - 1; // -1..1
      const y = h / 2 + v * (h / 2);
      const x = i * step;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  function drawCircular(ctx: CanvasRenderingContext2D, w: number, h: number) {
    if (!analyser || !freqData) return;
    analyser.getByteFrequencyData(freqData);

    const cx = w / 2;
    const cy = h / 2;
    const baseRadius = Math.min(w, h) * config.circularRadiusRatio;
    const barCount = Math.min(config.barCount, freqData.length);
    const binsPerBar = Math.floor(freqData.length / barCount) || 1;

    ctx.strokeStyle = resolveColorStyle(ctx, h);
    ctx.lineWidth = config.lineWidth;

    for (let i = 0; i < barCount; i++) {
      let sum = 0;
      for (let j = 0; j < binsPerBar; j++) sum += freqData[i * binsPerBar + j] ?? 0;
      const avg = sum / binsPerBar / 255;
      const angle = (i / barCount) * Math.PI * 2;
      const len = avg * baseRadius;

      const x1 = cx + Math.cos(angle) * baseRadius;
      const y1 = cy + Math.sin(angle) * baseRadius;
      const x2 = cx + Math.cos(angle) * (baseRadius + len);
      const y2 = cy + Math.sin(angle) * (baseRadius + len);

      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    }
  }

  function draw() {
    if (!canvasEl) return;
    const ctx = canvasEl.getContext("2d");
    if (!ctx) return;

    const w = canvasEl.width;
    const h = canvasEl.height;

    if (config.backgroundColor === "transparent") {
      ctx.clearRect(0, 0, w, h);
    } else {
      ctx.fillStyle = config.backgroundColor;
      ctx.fillRect(0, 0, w, h);
    }

    if (config.mode === "bars") drawBars(ctx, w, h);
    else if (config.mode === "wave") drawWave(ctx, w, h);
    else drawCircular(ctx, w, h);
  }

  function loop() {
    if (!running) return;
    draw();
    rafId = requestAnimationFrame(loop);
  }

  function connect(source: VisualizerSource) {
    ensureContext();
    if (!audioContext || !analyser) return;

    disconnect();

    if (source instanceof AudioBuffer) {
      const node = audioContext.createBufferSource();
      node.buffer = source;
      node.connect(analyser);
      node.connect(audioContext.destination);
      node.start();
      sourceNode = node;
    } else if (typeof MediaStream !== "undefined" && source instanceof MediaStream) {
      const node = audioContext.createMediaStreamSource(source);
      node.connect(analyser);
      // Deliberately not connected to destination — avoids feedback/echo for mic input.
      sourceNode = node;
    } else {
      const el = source as HTMLMediaElement;
      let node = mediaElementSourceCache.get(el);
      if (!node) {
        node = audioContext.createMediaElementSource(el);
        mediaElementSourceCache.set(el, node);
      }
      node.connect(analyser);
      node.connect(audioContext.destination);
      sourceNode = node;
    }
  }

  function disconnect() {
    sourceNode?.disconnect();
    sourceNode = null;
  }

  function start() {
    if (running) return;
    running = true;
    notify();
    loop();
  }

  function stop() {
    running = false;
    if (rafId !== null) cancelAnimationFrame(rafId);
    rafId = null;
    notify();
  }

  function setMode(mode: VisualizerMode) {
    config = { ...config, mode };
    notify();
  }

  function setConfig(patch: Partial<VisualizerConfig>) {
    config = { ...config, ...patch };
    if (analyser) {
      if (patch.fftSize !== undefined) {
        analyser.fftSize = patch.fftSize;
        freqData = new Uint8Array(new ArrayBuffer(analyser.frequencyBinCount));
        timeData = new Uint8Array(new ArrayBuffer(analyser.frequencyBinCount));
      }
      if (patch.smoothingTimeConstant !== undefined) {
        analyser.smoothingTimeConstant = patch.smoothingTimeConstant;
      }
    }
    notify();
  }

  return {
    connect,
    disconnect,
    start,
    stop,
    setMode,
    setConfig,
    isRunning: () => running,
    getMode: () => config.mode,

    attachCanvas: (el) => {
      canvasEl = el;
    },

    resume: async () => {
      if (audioContext?.state === "suspended") await audioContext.resume();
    },

    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    destroy: () => {
      stop();
      disconnect();
      audioContext?.close();
      audioContext = null;
      analyser = null;
      listeners.clear();
    },
  };
}

"use client";

import * as React from "react";
import type { VisualizerContextValue } from "./types";

export const VisualizerCtx = React.createContext<VisualizerContextValue | null>(null);

export function useVisualizerCtx(): VisualizerContextValue {
  const ctx = React.useContext(VisualizerCtx);
  if (!ctx) throw new Error("useVisualizerCtx must be used inside AudioVisualizerRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useVisualizerCtx } from "./visualizer-context";

export interface VisualizerCanvasProps {
  className?: string;
}

export function VisualizerCanvas({ className }: VisualizerCanvasProps) {
  const { engine } = useVisualizerCtx();
  const canvasRef = React.useRef<HTMLCanvasElement>(null);

  React.useEffect(() => {
    const el = canvasRef.current;
    engine.attachCanvas(el);
    return () => engine.attachCanvas(null);
  }, [engine]);

  React.useEffect(() => {
    const el = canvasRef.current;
    if (!el) return;

    const ratio = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;

    function resize() {
      if (!el) return;
      const { clientWidth, clientHeight } = el;
      el.width = Math.max(1, Math.round(clientWidth * ratio));
      el.height = Math.max(1, Math.round(clientHeight * ratio));
    }

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return <canvas ref={canvasRef} className={cn("block h-full w-full", className)} />;
}

VisualizerCanvas.displayName = "VisualizerCanvas";

"use client";

import * as React from "react";
import { VisualizerCtx } from "./visualizer-context";
import { createVisualizerEngine } from "./visualizer-engine";
import { VisualizerCanvas } from "./visualizer-canvas";
import type { VisualizerConfig } from "./types";

export interface AudioVisualizerRootProps {
  config?: VisualizerConfig;
  className?: string;
  /** Replace the default canvas layout entirely. */
  children?: React.ReactNode;
}

const DEFAULT_CONFIG: Required<VisualizerConfig> = {
  mode: "bars",
  fftSize: 256,
  smoothingTimeConstant: 0.8,
  barCount: 48,
  gapRatio: 0.3,
  color: "#c2f13c",
  colorStops: [],
  backgroundColor: "transparent",
  lineWidth: 2,
  circularRadiusRatio: 0.35,
};

export function AudioVisualizerRoot({ config, className, children }: AudioVisualizerRootProps) {
  const [engine] = React.useState(() => createVisualizerEngine(config));

  // Fires only on start()/stop()/setMode()/setConfig() — NOT per animation frame.
  // The render loop itself writes straight to canvas via requestAnimationFrame.
  const [, forceUpdate] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => engine.subscribe(forceUpdate), [engine]);
  React.useEffect(() => () => engine.destroy(), [engine]);

  const resolvedConfig: Required<VisualizerConfig> = { ...DEFAULT_CONFIG, ...config, mode: engine.getMode() };

  const ctx = {
    engine,
    config: resolvedConfig,
    isRunning: engine.isRunning(),
    mode: engine.getMode(),
  };

  return (
    <VisualizerCtx.Provider value={ctx}>
      {children ?? <VisualizerCanvas className={className} />}
    </VisualizerCtx.Provider>
  );
}

AudioVisualizerRoot.displayName = "AudioVisualizerRoot";

import { useVisualizerCtx } from "./visualizer-context";

/**
 * Call from anywhere under <AudioVisualizerRoot> to connect a source and control
 * playback of the visualization itself (independent from the audio's own play state).
 */
export function useAudioVisualizer() {
  const ctx = useVisualizerCtx();
  return {
    isRunning: ctx.isRunning,
    mode: ctx.mode,
    config: ctx.config,
    connect: ctx.engine.connect,
    disconnect: ctx.engine.disconnect,
    start: ctx.engine.start,
    stop: ctx.engine.stop,
    setMode: ctx.engine.setMode,
    setConfig: ctx.engine.setConfig,
    resume: ctx.engine.resume,
  };
}

export { AudioVisualizerRoot } from "./visualizer-root";
export { VisualizerCanvas } from "./visualizer-canvas";
export { useAudioVisualizer } from "./use-audio-visualizer";
export { useVisualizerCtx } from "./visualizer-context";
export { createVisualizerEngine } from "./visualizer-engine";
export type {
  VisualizerMode,
  VisualizerSource,
  VisualizerConfig,
  VisualizerEngine,
  VisualizerContextValue,
} from "./types";
